cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <float.h>

__global__ void softmax_kernel(const __half* __restrict__ input,
                               __half* __restrict__ output,
                               int dim) {
    int row = blockIdx.x;
    const __half* in_row = input + row * dim;
    __half* out_row = output + row * dim;

    // ---- max reduction ----
    float thread_max = -FLT_MAX;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float val = __half2float(in_row[i]);
        if (val > thread_max) thread_max = val;
    }
    __shared__ float smax[256];
    smax[threadIdx.x] = thread_max;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            float other = smax[threadIdx.x + stride];
            if (other > smax[threadIdx.x]) smax[threadIdx.x] = other;
        }
        __syncthreads();
    }
    float row_max = smax[0];

    // ---- sum of exp(x - max) reduction ----
    float thread_sum = 0.0f;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float val = __half2float(in_row[i]);
        thread_sum += expf(val - row_max);
    }
    __shared__ float ssum[256];
    ssum[threadIdx.x] = thread_sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            ssum[threadIdx.x] += ssum[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float row_sum = ssum[0];

    // ---- write softmax ----
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float val = __half2float(in_row[i]);
        float soft = expf(val - row_max) / row_sum;
        out_row[i] = __float2half(soft);
    }
}

torch::Tensor softmax_forward_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be half");
    auto batch = input.size(0);
    auto dim   = input.size(1);
    auto output = torch::empty_like(input);
    const int threads = 256;
    const dim3 blocks(batch);
    const auto stream = at::cuda::getCurrentCUDAStream();
    softmax_kernel<<<blocks, threads, 0, stream>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        dim);
    cudaGetLastError();  // propagate CUDA errors
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_forward_cuda", &softmax_forward_cuda, "Softmax forward (CUDA)");
}
'''

softmax_mod = load_inline(name='softmax_cuda',
                          cpp_sources='',
                          cuda_sources=cuda_source,
                          functions=['softmax_forward_cuda'],
                          verbose=False)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.to(torch.float16).contiguous()
        return softmax_mod.softmax_forward_cuda(x)

if __name__ == "__main__":
    batch_size = 4096
    dim = 393216
    x = torch.rand(batch_size, dim, device='cuda')
    model = ModelNew().cuda()
